function slugify($t){$m=['а'=>'a','б'=>'b','в'=>'v','г'=>'g','д'=>'d','е'=>'e','ё'=>'yo','ж'=>'zh','з'=>'z','и'=>'i','й'=>'y','к'=>'k','л'=>'l','м'=>'m','н'=>'n','о'=>'o','п'=>'p','р'=>'r','с'=>'s','т'=>'t','у'=>'u','ф'=>'f','х'=>'kh','ц'=>'ts','ч'=>'ch','ш'=>'sh','щ'=>'shch','ъ'=>'','ы'=>'y','ь'=>'','э'=>'e','ю'=>'yu','я'=>'ya'];return trim(preg_replace('/[^a-z0-9]+/','-',strtr(mb_strtolower($t),$m)),'-').'-'.substr(uniqid(),-6);}
function getDbSchema(){return <<<'SQLBLOCK'
CREATE TABLE IF NOT EXISTS `admin_users` (`id` int AUTO_INCREMENT PRIMARY KEY, `username` varchar(100) NOT NULL UNIQUE, `password_hash` varchar(255) NOT NULL, `totp_secret` varchar(64) DEFAULT NULL, `totp_enabled` tinyint(1) DEFAULT 0, `totp_backup_codes` text, `created_at` timestamp DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `offers` (`id` int AUTO_INCREMENT PRIMARY KEY, `title` varchar(500) NOT NULL, `slug` varchar(500) NOT NULL UNIQUE, `category` varchar(100) NOT NULL DEFAULT 'microloans', `amount_min` int DEFAULT 1000, `amount_max` int DEFAULT 100000, `term_min_days` int DEFAULT 1, `term_max_days` int DEFAULT 365, `psk` decimal(10,2) DEFAULT 0, `rate` decimal(10,2) DEFAULT 0, `rate_unit` varchar(10) DEFAULT 'day', `free_term_days` int DEFAULT 0, `logo_url` text, `affiliate_url` text, `borrower_category` varchar(50) DEFAULT 'any', `description` text, `seo_keywords` text, `regions` text, `rating` decimal(2,1) DEFAULT 5.0, `review_count` int DEFAULT 0, `is_active` tinyint(1) DEFAULT 1, `sort_order` int DEFAULT 0, `created_at` timestamp DEFAULT CURRENT_TIMESTAMP, `updated_at` timestamp DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, `age_min` int DEFAULT 18, `age_max` int DEFAULT 75, `documents` text, `requirements` text, `advantages` text, `application_time` varchar(100), `review_time` varchar(100), `payout_methods` text, `about_company` text, `meta_title` varchar(500), `meta_description` text, `features` text, `faq` text, `display_fields` text, `extra_fields` text) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `articles` (`id` int AUTO_INCREMENT PRIMARY KEY, `title` varchar(500) NOT NULL, `slug` varchar(500) NOT NULL UNIQUE, `excerpt` text, `content` text NOT NULL, `meta_title` varchar(255), `meta_description` text, `cover_image` text, `is_published` tinyint(1) DEFAULT 0, `sort_order` int DEFAULT 0, `created_at` timestamp DEFAULT CURRENT_TIMESTAMP, `updated_at` timestamp DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `reviews` (`id` int AUTO_INCREMENT PRIMARY KEY, `offer_id` int NOT NULL, `author_name` varchar(255) NOT NULL, `rating` int DEFAULT 5, `text` text NOT NULL, `pros` text, `cons` text, `is_approved` tinyint(1) DEFAULT 1, `created_at` timestamp DEFAULT CURRENT_TIMESTAMP, KEY `offer_id` (`offer_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `click_stats` (`id` int AUTO_INCREMENT PRIMARY KEY, `offer_id` int NOT NULL, `user_agent` text, `referer` text, `ip` varchar(45), `country` varchar(10), `utm_source` varchar(255), `utm_medium` varchar(255), `utm_campaign` varchar(255), `utm_content` varchar(255), `utm_term` varchar(255), `page_from` varchar(500), `ab_variant_id` int, `created_at` timestamp DEFAULT CURRENT_TIMESTAMP, KEY `offer_id` (`offer_id`), KEY `created_at` (`created_at`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

