CREATE TABLE IF NOT EXISTS `offer_tags` (`id` int AUTO_INCREMENT PRIMARY KEY, `slug` varchar(255) NOT NULL UNIQUE, `title` varchar(255) NOT NULL, `h1` varchar(500), `description` text, `meta_title` varchar(500), `meta_description` text, `content` text, `icon` varchar(10), `category` varchar(100) DEFAULT 'microloans', `features` text, `is_active` tinyint(1) DEFAULT 1, `sort_order` int DEFAULT 0, `search_queries` text, `created_at` timestamp DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `offer_tag_links` (`offer_id` int NOT NULL, `tag_id` int NOT NULL, PRIMARY KEY (`offer_id`,`tag_id`), KEY `idx_tag_id` (`tag_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `categories` (`id` int AUTO_INCREMENT PRIMARY KEY, `name` varchar(255) NOT NULL, `slug` varchar(255) NOT NULL UNIQUE, `icon` varchar(20), `h1` varchar(500), `description` text, `meta_title` varchar(500), `meta_description` text, `seo_text` text, `parent_id` int, `show_in_header` tinyint(1) DEFAULT 1, `show_in_footer` tinyint(1) DEFAULT 1, `footer_section` varchar(20) DEFAULT 'products', `field_templates` text, `is_active` tinyint(1) DEFAULT 1, `sort_order` int DEFAULT 0, `created_at` timestamp DEFAULT CURRENT_TIMESTAMP, KEY `idx_parent` (`parent_id`), KEY `idx_sort` (`sort_order`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

