CREATE TABLE IF NOT EXISTS `admin_login_log` (`id` int AUTO_INCREMENT PRIMARY KEY, `username` varchar(100), `ip` varchar(45) NOT NULL, `user_agent` text, `success` tinyint(1) DEFAULT 0, `created_at` timestamp DEFAULT CURRENT_TIMESTAMP, KEY `idx_ip` (`ip`), KEY `idx_created_at` (`created_at`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

