CREATE TABLE IF NOT EXISTS `city_seo_texts` (`id` int AUTO_INCREMENT PRIMARY KEY, `city_slug` varchar(255) NOT NULL, `category` varchar(100) DEFAULT 'microloans', `seo_title` varchar(500), `meta_title` varchar(500), `seo_h1` varchar(500), `seo_text` text, `meta_description` text, `generated_by` varchar(20) DEFAULT 'template', `created_at` timestamp DEFAULT CURRENT_TIMESTAMP, `updated_at` timestamp DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY `city_cat` (`city_slug`,`category`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `users` (`id` int AUTO_INCREMENT PRIMARY KEY, `email` varchar(255) NOT NULL UNIQUE, `password_hash` varchar(255) NOT NULL, `name` varchar(255), `is_verified` tinyint(1) DEFAULT 0, `verify_code` varchar(10), `verify_code_expires` timestamp NULL, `last_login_at` timestamp NULL, `last_login_ip` varchar(45), `agreed_terms` tinyint(1) DEFAULT 0, `agreed_marketing` tinyint(1) DEFAULT 0, `agreed_finance` tinyint(1) DEFAULT 0, `created_at` timestamp DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `user_favorites` (`id` int AUTO_INCREMENT PRIMARY KEY, `user_id` int NOT NULL, `offer_id` int NOT NULL, UNIQUE KEY `user_offer` (`user_id`,`offer_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `user_applications` (`id` int AUTO_INCREMENT PRIMARY KEY, `user_id` int NOT NULL, `offer_id` int NOT NULL, `click_stat_id` int, `ip` varchar(45), `status` varchar(50) DEFAULT 'pending', `created_at` timestamp DEFAULT CURRENT_TIMESTAMP, KEY `idx_user_id` (`user_id`), KEY `idx_offer_id` (`offer_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `user_login_log` (`id` int AUTO_INCREMENT PRIMARY KEY, `user_id` int, `email` varchar(255), `ip` varchar(45), `success` tinyint(1) DEFAULT 0, `created_at` timestamp DEFAULT CURRENT_TIMESTAMP, KEY `idx_user_id` (`user_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `postback_conversions` (`id` int AUTO_INCREMENT PRIMARY KEY, `click_id` varchar(255), `transaction_id` varchar(255), `offer_id` int, `external_offer_id` varchar(100), `status` varchar(50) NOT NULL, `payout` decimal(10,2) DEFAULT 0, `ip` varchar(45), `aff_sub` varchar(500), `aff_sub2` varchar(500), `aff_sub3` varchar(500), `goal_id` varchar(100), `raw_query` text, `created_at` timestamp DEFAULT CURRENT_TIMESTAMP, KEY `idx_click_id` (`click_id`), KEY `idx_status` (`status`), KEY `idx_offer_id` (`offer_id`), KEY `idx_created_at` (`created_at`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

