CREATE TABLE IF NOT EXISTS `ab_tests` (`id` int AUTO_INCREMENT PRIMARY KEY, `name` varchar(255) NOT NULL, `is_active` tinyint(1) DEFAULT 1, `category_scope` varchar(100) DEFAULT 'all', `created_at` timestamp DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `ab_variants` (`id` int AUTO_INCREMENT PRIMARY KEY, `test_id` int NOT NULL, `label` varchar(100) NOT NULL, `color` varchar(50) DEFAULT '#059669', `impressions` int DEFAULT 0, `clicks` int DEFAULT 0, KEY `idx_test_id` (`test_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

