CREATE TABLE IF NOT EXISTS `newsletter_send_log` (`id` int AUTO_INCREMENT PRIMARY KEY, `newsletter_id` int NOT NULL, `subscriber_id` int, `email` varchar(255) NOT NULL, `status` varchar(20) DEFAULT 'sent', `error_message` varchar(500), `is_test` tinyint(1) DEFAULT 0, `sent_at` timestamp DEFAULT CURRENT_TIMESTAMP, KEY `idx_newsletter` (`newsletter_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `newsletter_events` (`id` int AUTO_INCREMENT PRIMARY KEY, `newsletter_id` int NOT NULL, `subscriber_id` int NOT NULL, `event_type` varchar(10) NOT NULL, `url` text, `ip` varchar(45), `created_at` timestamp DEFAULT CURRENT_TIMESTAMP, KEY `idx_newsletter_id` (`newsletter_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `offer_link_checks` (`id` int AUTO_INCREMENT PRIMARY KEY, `offer_id` int NOT NULL, `url` text NOT NULL, `http_code` int, `final_url` text, `redirect_count` int DEFAULT 0, `is_ok` tinyint(1) DEFAULT 0, `error_message` text, `checked_at` timestamp DEFAULT CURRENT_TIMESTAMP, KEY `offer_id` (`offer_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci
