function getArchive(){return '';}
if($step==='install'&&$_SERVER['REQUEST_METHOD']==='POST'){
$dbHost=trim($_POST['db_host']??'localhost');$dbName=trim($_POST['db_name']??'');$dbUser=trim($_POST['db_user']??'');$dbPass=$_POST['db_pass']??'';
$adminUser=trim($_POST['admin_user']??'admin');$adminPass=$_POST['admin_pass']??'';
$siteName=trim($_POST['site_name']??'Космозайм');$siteUrl=rtrim(trim($_POST['site_url']??''),'/');
if(!$dbName||!$dbUser)$error='Заполните данные БД';
elseif(strlen($adminPass)<6)$error='Пароль мин. 6 символов';
elseif(!$siteUrl)$error='Укажите URL';
else{try{
$tmp=__DIR__.'/_kosmo_tmp.tar.gz';file_put_contents($tmp,base64_decode(getArchive()));
shell_exec('cd '.escapeshellarg(__DIR__).' && tar xzf _kosmo_tmp.tar.gz 2>&1');
if(!file_exists(__DIR__.'/index.php')&&class_exists('PharData')){$phar=new PharData($tmp);$phar->extractTo(__DIR__,null,true);}
@unlink($tmp);if(!file_exists(__DIR__.'/index.php'))throw new Exception('Файлы не распакованы');
foreach(['data','data/cache','data/geo_cache','images/articles','images/offer'] as $d)@mkdir(__DIR__.'/'.$d,0755,true);
file_put_contents(__DIR__.'/.htaccess',"AddDefaultCharset UTF-8\n\nRewriteEngine On\nRewriteCond %{REQUEST_FILENAME} !-f\nRewriteCond %{REQUEST_FILENAME} !-d\nRewriteRule ^(.*)\$ index.php [QSA,L]\n\n<IfModule mod_expires.c>\nExpiresActive On\nExpiresByType image/jpeg \"access plus 1 month\"\nExpiresByType image/png \"access plus 1 month\"\nExpiresByType image/svg+xml \"access plus 1 month\"\nExpiresByType text/css \"access plus 1 week\"\nExpiresByType application/javascript \"access plus 1 week\"\n</IfModule>\n\n<IfModule mod_deflate.c>\nAddOutputFilterByType DEFLATE text/html text/css application/javascript application/json image/svg+xml\n</IfModule>\n\n<FilesMatch \"\\.(env|log|json|txt)\$\">\n<IfModule mod_authz_core.c>\nRequire all denied\n</IfModule>\n</FilesMatch>\n\n<FilesMatch \"^\\.\">\n<IfModule mod_authz_core.c>\nRequire all denied\n</IfModule>\n</FilesMatch>\n");
file_put_contents(__DIR__.'/.env',"DB_HOST=$dbHost\nDB_NAME=$dbName\nDB_USER=$dbUser\nDB_PASS=$dbPass\nNEXT_PUBLIC_SITE_URL=$siteUrl\nSESSION_SECRET=".bin2hex(random_bytes(32))."\nCRON_SECRET=".bin2hex(random_bytes(16))."\n");
@chmod(__DIR__.'/.env',0600);
$cfg=file_get_contents(__DIR__.'/config.php');
$cfg=str_replace("'https://kosmozaim.ru'","'".$siteUrl."'",$cfg);
$cfg=str_replace("'partnerka72_kosmonew'","''",$cfg);
$cfg=str_replace("'partnerka72'","''",$cfg);
file_put_contents(__DIR__.'/config.php',$cfg);
file_put_contents(__DIR__.'/data/site-settings.json',json_encode(['site_name'=>$siteName,'site_url'=>$siteUrl],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE));
$pdo=new PDO("mysql:host=$dbHost;charset=utf8mb4",$dbUser,$dbPass,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);
$pdo->exec("CREATE DATABASE IF NOT EXISTS `$dbName` CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci");
$pdo->exec("USE `$dbName`");
$pdo->exec("SET FOREIGN_KEY_CHECKS=0");
foreach(['newsletter_events','newsletter_send_log','offer_link_checks','postback_conversions','postback_profiles','user_applications','user_favorites','user_login_log','users','city_seo_texts','admin_audit_log','admin_ip_whitelist','admin_login_log','page_views','offer_tag_links','offer_tags','geo_redirects','subscribers','click_stats','reviews','articles','offers','categories','ab_variants','ab_tests','newsletters','admin_users'] as $tbl){$pdo->exec("DROP TABLE IF EXISTS `$tbl`");}
$pdo->exec("SET FOREIGN_KEY_CHECKS=1");
foreach(array_filter(array_map('trim',preg_split('/;\s*[\r\n]+/',getDbSchema())))as$q){if($q&&$q[0]!=='-')$pdo->exec($q);}
$pdo->prepare("INSERT INTO admin_users (username,password_hash) VALUES (?,?)")->execute([$adminUser,password_hash($adminPass,PASSWORD_DEFAULT)]);
$cats=[
['Займы','zajmy','💵','Займы онлайн','Займы онлайн — Подбор микрозаймов','Подберите выгодный микрозайм онлайн.',1,1,'products',1],
['Кредиты','kredity','🏦','Кредиты онлайн','Кредиты онлайн — Сравнение','Сравните условия банковских кредитов.',1,1,'products',2],
['Кредитные карты','karty-kreditnye','💳','Кредитные карты','Кредитные карты онлайн — Сравнение','Сравните кредитные карты.',1,1,'products',3],
['Дебетовые карты','karty-debetovye','🪪','Дебетовые карты','Дебетовые карты','Сравните дебетовые карты.',1,1,'products',4],
['Сравнение','compare','⚖️','Сравнение предложений',null,null,1,1,'tools',10],
['Калькулятор','calculator','🧮','Калькулятор займа',null,null,1,1,'tools',11],
['Статьи','articles','📰','Полезные статьи',null,null,1,1,'tools',12],
['FAQ','faq','❓','Частые вопросы',null,null,0,1,'tools',13],
['Глоссарий','glossary','📖','Глоссарий терминов',null,null,0,1,'tools',14],
];
$st=$pdo->prepare("INSERT INTO categories (name,slug,icon,h1,meta_title,meta_description,show_in_header,show_in_footer,footer_section,sort_order,is_active) VALUES (?,?,?,?,?,?,?,?,?,?,1)");
foreach($cats as $c)$st->execute($c);
$tags=[
['bez-otkaza','Займы без отказа','Займы без отказа на карту онлайн','✅','microloans','МФО с высоким процентом одобрения','Займы без отказа на карту за 5 минут.'],
['bez-protsentov','Займы без процентов','Займы без процентов — первый займ под 0%','🆓','microloans','Бесплатные займы для новых клиентов','Займы без процентов на карту.'],
['na-kartu','Займы на карту','Займы на карту мгновенно онлайн','💳','microloans','Получите деньги на банковскую карту','Займы на карту мгновенно.'],
['s-plohoj-kreditnoj-istoriej','Займы с плохой КИ','Займы с плохой кредитной историей','📊','microloans','Займы даже с испорченной КИ','Займы с плохой кредитной историей.'],
['dlya-pensionerov','Займы для пенсионеров','Займы для пенсионеров онлайн','👴','microloans','Специальные условия для пенсионеров','Займы для пенсионеров без отказа.'],
['studentam','Займы студентам','Займы студентам онлайн','🎓','microloans','Займы для студентов от 18 лет','Займы студентам на карту.'],
];
$st=$pdo->prepare("INSERT INTO offer_tags (slug,title,h1,icon,category,description,meta_description,is_active,sort_order) VALUES (?,?,?,?,?,?,?,1,?)");
foreach($tags as $i=>$t)$st->execute([$t[0],$t[1],$t[2],$t[3],$t[4],$t[5],$t[6],$i+1]);
$offers=[['Пример МФО 1','microloans',1000,30000,0.8,'day',14,'Быстрые займы онлайн'],['Пример МФО 2','microloans',5000,100000,0.99,'day',7,'Деньги за 5 минут'],['Пример Банк','credits',50000,5000000,15.9,'year',0,'Кредит наличными'],['Пример Карта','credit_cards',0,500000,24.9,'year',55,'Кредитная карта']];
$st=$pdo->prepare("INSERT INTO offers (title,slug,category,amount_min,amount_max,rate,rate_unit,free_term_days,affiliate_url,description,is_active,sort_order) VALUES (?,?,?,?,?,?,?,?,'',?,1,?)");
foreach($offers as $i=>$o)$st->execute([$o[0],slugify($o[0]),$o[1],$o[2],$o[3],$o[4],$o[5],$o[6],$o[7],$i+1]);
$pdo->exec("INSERT IGNORE INTO offer_tag_links (offer_id,tag_id) SELECT o.id,t.id FROM offers o,offer_tags t WHERE o.category='microloans' AND t.category='microloans'");
// Города берутся из data/cities.php, geo_redirects — для перенаправления по странам
$step='done';
}catch(Exception $e){$error=$e->getMessage();@unlink(__DIR__.'/_kosmo_tmp.tar.gz');}}}
?>
